insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Bayberry Grooming','Pet Services','Service area only','',null,'https://www.bayberrygrooming.com/','Mobile dog grooming website lists Mountain House, Tracy, Lathrop and Manteca. Offers bath and haircut services. New clients are directed to a waitlist; an appointment is not guaranteed. Use the website to confirm your address, grooming needs and availability. Office address and public phone not established.','approved',true,false,null,0,'editorial_first_party','https://www.bayberrygrooming.com/aboutus','first_party_website_desk_check',now()) returning id into bid;
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://www.bayberrygrooming.com/aboutus',array['identity','website','advertised services','advertised service area'],array['Mountain House','Tracy','Lathrop','Manteca'],array['mobile dog grooming','dog grooming'],'First-party website desk check of identity, mobile dog grooming and four explicit service areas. New-client waitlist visibly checked. No public phone or office address established; no independent credential, insurance, quality or availability validation. No provider images reused. Sources: https://www.bayberrygrooming.com/aboutus https://www.bayberrygrooming.com/ https://www.bayberrygrooming.com/intakeform');
