insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('iThink Pet','Pet Services','Service area only','','(510) 274-1750','https://www.ithinkpet.com/','Advertises pet sitting and dog walking with Central Valley coverage explicitly including Mountain House, Tracy, Lathrop and Manteca. The website lists a public text number and travel fees for Mountain House, Lathrop and Manteca. Confirm pet needs, quote, holiday charges and availability directly; office address not established.','approved',true,false,null,0,'editorial_first_party','https://www.ithinkpet.com/central-valley-rates.html','first_party_website_desk_check',now()) returning id into bid;
