insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Weekly Meditation — November 14','Adult guided breathing and relaxation session at the library; no prior experience needed. Covers the November 14 occurrence only. The official calendar lists 10:30 AM–noon; confirm attendance arrangements with the branch.','Mountain House','Mountain House Branch Library, 201 E Main Street, Mountain House','2026-11-14T10:30:00-08:00','2026-11-14T12:00:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/mountain-house/weekly-meditation?id=1794681000-225009','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Mountain House' and source_url='https://www.ssjcpl.org/events-services/events-calendar/mountain-house/weekly-meditation?id=1794681000-225009' and start_date='2026-11-14T10:30:00-08:00'::timestamptz);
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'English Conversation Club for Adults — November 20','Adults can practice English conversation at the library. November 20 date, time and room checked against the exact official occurrence. This entry does not include the skipped November 13 or November 27 dates; confirm attendance details with the branch.','Tracy','Tracy Branch Library, Wadsworth Room, 20 E Eaton Avenue, Tracy','2026-11-20T16:00:00-08:00','2026-11-20T17:00:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/tracy/reoccurring-weekly-monthly-events/english-conversation-club-for-adults?id=1795219200-211630','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Tracy' and source_url='https://www.ssjcpl.org/events-services/events-calendar/tracy/reoccurring-weekly-monthly-events/english-conversation-club-for-adults?id=1795219200-211630' and start_date='2026-11-20T16:00:00-08:00'::timestamptz);
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Tween: Random Fandom Key Chains (Ages 8–12)','Ages 8–12 can make a fandom-themed key chain. Online registration is required; spaces are limited and may fill. The organizer asks registrants to check in at 3:50 PM, with a five-minute grace period after the start. Check the official page for current availability; no space is reserved through MoHoLocal.','Lathrop','Lathrop Branch Library, 450 Spartan Way, Lathrop','2026-11-12T16:00:00-08:00','2026-11-12T17:00:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/lathrop/tween-random-fandom-key-chains?id=1794528000-247454','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Lathrop' and source_url='https://www.ssjcpl.org/events-services/events-calendar/lathrop/tween-random-fandom-key-chains?id=1794528000-247454' and start_date='2026-11-12T16:00:00-08:00'::timestamptz);
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'The Grim Readers — Teen Horror Book Club','Horror-reading discussion for teens ages 13–17. Covers the November 12 occurrence only. Advance registration is encouraged by the organizer; confirm attendance and the current reading selection directly, as older book announcements remain on the source page.','Manteca','Manteca Branch Library, 320 W Center Street, Manteca','2026-11-12T16:30:00-08:00','2026-11-12T17:30:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/manteca-branch/the-grim-readers-a-horror-book-club-for-teens?id=1794529800-230218','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Manteca' and source_url='https://www.ssjcpl.org/events-services/events-calendar/manteca-branch/the-grim-readers-a-horror-book-club-for-teens?id=1794529800-230218' and start_date='2026-11-12T16:30:00-08:00'::timestamptz);
