begin;
do $curate$ declare bid uuid; begin
if exists(select 1 from public.businesses where website ilike '%bayberrygrooming.com%' or lower(name)=lower('Bayberry Grooming') ) then raise exception 'Duplicate provider requires review'; end if;
end $curate$;
do $curate$ declare bid uuid; begin
if exists(select 1 from public.businesses where website ilike '%ithinkpet.com%' or lower(name)=lower('iThink Pet') or regexp_replace(coalesce(phone,''),'[^0-9]','','g') like '%5102741750') then raise exception 'Duplicate provider requires review'; end if;
end $curate$;
commit;
